    mahjong_new_game: "Nieuw spel",
    mahjong_shuffle: "Resterende stenen schudden",
    chess_history_intro: "Van een oud Indiaas oorlogsspel tot 's werelds meest bestudeerde bordspel - schaken heeft continenten en eeuwen doorkruist om te worden wat het vandaag is.",
    go_history_intro: "Go is een van de oudste bordspellen die nog in zijn originele vorm gespeeld wordt - een spel van gebied en stenen met wortels die vermoedelijk meer dan 2500 jaar terugreiken tot China.",
    checkers_history_intro: "Dammen is een spel van eenvoudige regels en diepe strategie, ontstaan uit de combinatie van een eeuwenoud bord met een nieuwere manier van slaan.",
    ur_history_intro: "Met een leeftijd van zo'n 4600 jaar is het Koninklijk Spel van Ur een van de oudste ooit ontdekte bordspellen - en, dankzij speurwerk dat twee millennia overspant, een van de weinige oude spellen die we nog volgens de originele regels kunnen spelen.",
    morris_history_intro: "Weinig spellen zijn in zoveel verschillende oppervlakken gekrast over zoveel eeuwen als het Molenspel - van Egyptische tempeldaken tot Engelse kathedraalkloosters.",
    backgammon_history_intro: "De stamboom van backgammon loopt door bijna elke beschaving die ooit met dobbelstenen heeft gegooid - van het oude Mesopotamië en Rome tot de koffiehuizen van het hedendaagse Midden-Oosten.",
    xiangqi_history_intro: "Chinees schaak deelt diepe wortels met internationaal schaken, maar volgde meer dan duizend jaar lang zijn eigen weg om te worden tot het spel dat vandaag door honderden miljoenen mensen wordt gespeeld.",
    mancala_history_intro: "Mancala is niet één spel maar een hele spelfamilie - een van de oudste spelfamilies op aarde, opgebouwd rond de eenvoudige, universele handeling van zaadjes of stenen tussen kuilen verplaatsen.",
    reversi_history_intro: "Een Victoriaans gezelschapsspel, twee keer opnieuw uitgevonden met een eeuw ertussen.",
    fourinarow_history_intro: "Een simpel, door de zwaartekracht aangedreven idee dat uitgroeide tot een van de bestverkochte spellen van de 20e eeuw.",
    gomoku_history_intro: "Een simpel spel waarbij je stenen op een rij zet, waarvan juist de eenvoud competitieve spelers dwong de regels aan te passen.",
    tictactoe_history_intro: "Waarschijnlijk het bekendste spel voor papier en potlood – met wortels in het oude Rome en een plek in de geschiedenis van de computer.",
    senet_history_intro: "Een van de oudste ooit gevonden bordspellen - en een waarvan de exacte regels al duizenden jaren verloren zijn.",
    shogi_history_intro: "Japans eigen kijk op de schaakfamilie, en de enige grote variant waarbij een geslagen stuk het spel niet verlaat - het sluit zich aan bij de kant die het sloeg.",
    sudoku_history_intro: "Anders dan elk ander spel in deze verzameling heeft Sudoku helemaal geen oude afkomst - het is nauwelijks ouder dan de personal computer.",
    pegsolitaire_history_intro: "Een eenspelerspuzzel oud genoeg om een eigen hoflegende te hebben, en het onderwerp van een van de verrassendere resultaten in de recreatieve wiskunde.",
    minesweeper_history_intro: "Een puzzel waarvan de bepalende regel - een volkomen veilige eerste zet - pas standaard werd zodra computers, in plaats van een gedrukte pagina, op verzoek een vers bord konden genereren.",
    nonogram_history_intro: "Een logicapuzzel, onafhankelijk van elkaar uitgevonden aan tegenovergestelde kanten van de wereld, binnen een paar jaar van elkaar - en vernoemd naar een van zijn twee uitvinders.",
    twenty48_history_intro: "Een spel dat bijna volledig is opgebouwd uit ideeën van andere spellen, in een weekend gemaakt, en door meer mensen gekloond dan misschien wel elk browserspel ervoor.",
    mahjong_history_intro: "Een eenspelers-tegelparingsspel, genoemd naar en visueel geleend van een compleet ander vierspelersspel waarmee het verder vrijwel niets gemeen heeft.",
