    update_banner_text: "Er is een nieuwe versie van PaperGames beschikbaar.",
    update_banner_new_games: "Nieuw sinds je laatste bezoek: {s}.",
    update_banner_more_games: "nog {n}",
    update_banner_list_sep: ", ",
    update_banner_more_notes: "En meer verbeteringen.",
    release_v223: "Offline opslaan werkt betrouwbaarder, spellen zijn in families ingedeeld, Domino heeft de variant ‘Driehoeken’, en ‘Wie heeft de taart gepakt?’ heeft het thema ‘Katten en vis’ en geeft meer hints.",
    release_v224: "Kaartduel: vier even sterke decks, tegen de computer of met z’n tweeën op één apparaat.",
    release_v225: "Sprookjesschurken: zes schurken uit de sprookjes van Grimm met eigen doelen, voor 2 tot 4 spelers.",
    release_v226: "Bosdorp: bosdieren bouwen door de seizoenen heen een dorp, voor 1 tot 4 spelers.",
    release_v227: "Avonturenboek: een rollenspel voor één persoon – maak een held en verken een grot, een toren of een bos.",
    release_v228: "Een kleine link onderaan de startpagina leidt naar Quillwild, een nieuw project in de maak.",
    release_v229: "De startpagina is nu korter; de categorieën hebben eigen pagina’s.",
    release_v230: "Kaartduel: alle kaarten hebben nu een afbeelding.",
    release_v234: "Tangram heeft een nieuw niveau, ‘Alleen omtrek’, met 29 nieuwe figuren.",
    release_v235: "Zoekplaat met negen kamers en meer dan 40 nieuwe tekeningen; ‘Wie heeft de taart gepakt?’ met een familie, en met kinderen en een schat.",
    release_v236: "Zoekplaat met badkamer, kelder en slaapkamer; ‘Wie heeft de taart gepakt?’ met vijf kamers meer en zeven nieuwe meubels.",
    release_v237: "‘Nieuwe spellen’ toont nu de 10 nieuwste spellen.",
    release_v241: "Waldsiedlung heeft nieuwe regels, een nieuwe naam en aangepaste beschrijvingen; oude spelgegevens worden verwijderd.",
    release_v242: "Het spel heeft een nieuwe naam en een nieuw adres; oude adressen verwijzen door.",
    release_v243: "De offlineopslag laadt minder opnieuw; Arabische tussenruimtes zijn hersteld, actieve knoppen zijn zwart, ‘Schudden’ vraagt eerst om bevestiging en regelpagina’s hebben bovenaan een teruglink.",
    release_v244: "Spellen openen meteen speelklaar; het resultaatvenster heeft «Nog een keer»; «Nieuw spel» staat naast het bord; schaken heeft een eigen knop voor twee spelers.",
    release_v245: "Spelpagina’s hebben een kop van één regel en geen sitenavigatie; instellingen zitten nu in het menu; het bedieningspaneel sluit na de start, zodat meer borden op het scherm passen.",
    release_v246: "Spelkaarten op alle categoriepagina’s zijn grote tikvlakken; de kinderpagina toont alle kinderspellen op één pagina met grote symbolen; «Groot bord» maakt kleine borden makkelijker te tikken; Cake staat niet meer bij de kinderspellen.",
    release_v248: "Zeven nieuwe spellen (bingo, drie dobbelspellen en drie kinderpuzzels), een nieuw zeer moeilijk niveau bij het pijlenspel, een hulpknop bij het kattenspel, betere zoekfunctie en de pagina Kaartspellen.",
    release_v247: "Alle spellen gebruiken dezelfde namen en statusteksten („Tegen de computer”, „Met twee op één apparaat”, „Nieuw spel”, „Jij bent aan de beurt”); elke spelpagina heeft een Home-knop; „Ongedaan maken” neemt je zet en het antwoord van de computer terug in 32 spellen.",
    release_v240: "De spelnamen zijn in alle 12 talen gewijzigd.",
    release_v239: "Beschermde spelnamen zijn verwijderd uit regels en beschrijvingen van geschiedenispagina’s.",
    release_v238: "De korte regels passen nu bij het gekozen taartmotief en de zoekplaat.",
    release_v233: "Pijlen op Moeilijk: glijdende pijlen, 11 × 11 vakjes en een nieuw niveau Meester met drie hartjes.",
    release_v232: "Zetsuggesties kun je uitzetten in de instellingen, en ‘Wie heeft de taart gepakt?’ heeft drie nieuwe thema's.",
    release_v231: "Zoek de verschillen heeft een nieuwe spelvorm: de zoekplaat.",
    update_banner_reload: "Nu vernieuwen",
    update_banner_dismiss: "Sluiten",
    error_banner_text: "Er is iets misgegaan. Opnieuw laden kan helpen.",
    storage_warning_text: "Je voortgang kon niet worden opgeslagen. De opslag is mogelijk vol of niet beschikbaar (bijv. privébrowsen).",
    resign_confirm_dialog: "Deze partij opgeven?",
    new_game_confirm_dialog: "Nieuw spel starten? Je huidige partij gaat verloren, maar telt niet als verlies in je statistieken.",
    stats_empty: "Nog geen partijen tegen de computer gespeeld.",
    stats_reset_button: "Statistieken resetten",
    stats_reset_confirm: "Alle statistieken resetten? Dit kan niet ongedaan worden gemaakt.",
    home_coming_soon_title: "Binnenkort",
    home_coming_soon_intro: "Meer spellen die worden overwogen voor een toekomstige update:",
    home_coming_soon_multiplayer_title: "Strategiespellen voor twee spelers",
    home_coming_soon_solo_title: "Eenspelerspuzzels",
    game_four_in_a_row: "Vier op een Rij",
    home_four_in_a_row_desc: "Laat schijven vallen om als eerste vier op een rij te krijgen. Lokaal met z'n tweeën of tegen de ingebouwde engine.",
    game_gomoku: "Gomoku (Vijf op een Rij)",
    home_gomoku_desc: "Krijg als eerste vijf stenen op een rij, op een bord ter grootte van Go. Lokaal met z'n tweeën of tegen de ingebouwde engine.",
    game_tictactoe: "Boter-kaas-en-eieren",
    home_tictactoe_desc: "Drie op een rij op een veld van 3x3 – de klassieker voor papier en potlood. Lokaal met 2 spelers of tegen de ingebouwde engine, die op Moeilijk nooit verliest.",
    tictactoe_board_label: "Bord voor boter-kaas-en-eieren",
    game_alquerque: "Alquerque",
    home_alquerque_desc: "De middeleeuwse voorouder van dammen: elk 12 stukken op een 5x5-bord van lijnen, slaan door te springen, en slaan is verplicht. Lokaal met twee spelers of tegen de ingebouwde engine.",
    alquerque_board_label: "Alquerque-bord",
    msg_keep_jumping: "Blijf springen met dit stuk.",
    alquerque_history_intro: "Een klein springspel op een bord van lijnen, opgeschreven in het Spanje van de 13e eeuw - en de voorouder van dammen.",
    game_pairs: "Paren",
    home_pairs_desc: "Draai twee kaarten om en vind de paren: het klassieke spel van kaarten koppelen, met eenvoudige zwart-witte vormen, dieren, groente en fruit of voertuigen. Solo tegen het aantal zetten, met twee spelers op één apparaat of tegen de ingebouwde engine.",
    game_futoshiki: "Futoshiki",
    home_futoshiki_desc: "Vul het rooster zo dat elke rij en kolom elk getal één keer bevat - en elk teken tussen twee vakjes naar het kleinere getal wijst. 4x4 tot 6x6, vers gemaakt met één oplossing.",
    futoshiki_board_label: "Futoshiki-bord",
    futoshiki_size_label: "Roostergrootte",
    futoshiki_history_intro: "Een Japanse getallenpuzzel waarvan de naam gewoon ongelijkheid betekent: een Latijns vierkant met kleine tekens tussen de vakjes.",
    game_foxandgeese: "Vos en Ganzen",
    home_foxandgeese_desc: "Het middeleeuwse jachtspel op het kruis met 33 punten: één vos tegen 13 ganzen. Speel een van beide kanten, lokaal met z'n tweeën of tegen de ingebouwde engine.",
    foxandgeese_board_label: "Vos-en-Ganzen-bord",
    foxandgeese_history_intro: "Een jachtspel uit het middeleeuwse Europa: een vos, een troep ganzen en een kruisvormig bord.",
    game_seega: "Seega",
    home_seega_desc: "Een Egyptisch plaats- en insluitspel op 5x5 velden: eerst plaatsen beide kanten hun 12 stenen, daarna wordt geslagen door in te sluiten. Lokaal met z'n tweeën of tegen de ingebouwde engine.",
    seega_board_label: "Seega-bord",
    seega_history_intro: "Een spel uit Egypte, beschreven in 1836: plaats je stenen per twee en sluit daarna de tegenstander in tussen twee van je eigen stenen.",
    game_romme: "Rummy (Rommé)",
    home_romme_desc: "De Duitse rummy met twee spellen en zes jokers: leg sets en rijen uit, leg aan bij elke combinatie op tafel en raak al je kaarten kwijt. 2 tot 4 spelers, tegen de computer of op één apparaat.",
    romme_history_intro: "De rummy zoals die in Duitsland met twee spellen en jokers wordt gespeeld – een van de vele spellen waarin je sets en reeksen verzamelt.",
    romme_meld_button: "Uitleggen",
    romme_confirm_button: "Eerste uitleg leggen",
