    seo_title_index: "PaperGames – {games} gratis bordspellen voor e-readers",
    seo_desc_index: "{games} klassieke bordspellen voor e-readers en tablets. Schaken, go, backgammon, sudoku en meer. Gratis, offline, zonder reclame, in 12 talen.",
    seo_title_about: "Over PaperGames – {games} gratis bordspellen voor e-ink",
    seo_desc_about: "Waarom PaperGames bestaat, hoe het gemaakt is en hoe je het project kunt steunen. Een gratis, offline en reclamevrije verzameling van {games} klassieke bord- en puzzelspellen.",
    nav_calm: "Rustig spelen",
    about_calm_link: "Rustig spelen: geen animaties, geen geluid, geen reclame",
    calm_intro: "PaperGames is gemaakt om rustig te spelen. Dat betekent:",
    calm_point_1: "Geen animaties: niets knippert, schuift of springt. Elke verandering verschijnt in één keer.",
    calm_point_2: "Geen geluid.",
    calm_point_3: "Geen reclame, geen meldingen. Je hebt geen account nodig – alleen online schaken loopt via een Lichess-account.",
    calm_point_4: "Geen tracking, geen cookies. Opgeslagen spellen en statistieken blijven in de browser op je apparaat.",
    calm_point_5: "Gemaakt voor e-readers met e-ink: donkere tekst op een lichte achtergrond, en verschillen worden nooit alleen met grijs of kleur getoond.",
    calm_point_6: "Geen tijdsdruk. Uitzonderingen: Stad, land, rivier met een instelbare rondetijd (standaard uit), de meelopende klok bij Minesweeper en de bedenktijd bij online schaken op Lichess.",
    calm_point_7: "Na het eerste bezoek werkt alles zonder internet, als de browser dat ondersteunt – behalve online schaken.",
    calm_point_8: "Ook voor kinderen: in de spellen valt niets te kopen en niets te delen. De pagina ‘Over’ bevat een vrijwillige donatielink naar PayPal.",
