    game_senet: "Senet",
    home_senet_desc: "Een van de oudste bekende bordspellen, uit het oude Egypte. Lokaal met z'n tweeën of tegen de ingebouwde engine.",
    game_shogi: "Shogi",
    home_shogi_desc: "Japans schaak, waarbij geslagen stukken van kant wisselen en weer meedoen aan de strijd. Lokaal met z'n tweeën of tegen de ingebouwde engine.",
    game_card_tactics: "Kaarttactiek",
    home_card_tactics_desc: "Een snel, elegant duel dat wordt beslist door vijf wisselende zetkaarten. Lokaal met z'n tweeën of tegen de ingebouwde engine.",
    cardtactics_neutral_card: "Volgende kaart:",
    cardtactics_history_intro: "Een moderne toevoeging aan de familie van abstracte strategiespellen, opgebouwd rond een kleine twist op schaakachtige beweging: in plaats van dat elk stuk een vaste manier van bewegen heeft, bepaalt een gedeeld kaartdeck wat er van beurt tot beurt mogelijk is.",
    game_hnefatafl: "Hnefatafl (Vikingschaak)",
    home_hnefatafl_desc: "Een asymmetrisch Noords spel: de koning moet ontsnappen, de aanvallers moeten hem gevangen zetten. Lokaal met z'n tweeën of tegen de ingebouwde engine.",
    hnefatafl_history_intro: "Een van de oudste bordspelfamilies van Noord-Europa, eeuwenlang gespeeld in de Vikingwereld voordat schaken daar ooit aankwam.",

    game_tablut: "Tablut",
    home_tablut_desc: "Het grootste en best gedocumenteerde Tafl-spel: een 9x9-bord waarop de koning een hoek moet bereiken en de aanvallers hem eerst moeten vangen.",
    tablut_history_intro: "Het best gedocumenteerde lid van de hele Tafl-familie, dankzij het notitieboekje van één achttiende-eeuwse natuuronderzoeker.",

    game_wall_maze: "Muurlabyrint",
    home_wall_maze_desc: "Race naar de overkant van het bord terwijl je muren bouwt om je tegenstander te blokkeren. Lokaal met z'n tweeën of tegen de ingebouwde engine.",
    wallmaze_history_intro: "Het Muurlabyrint is een modern abstract strategiespel dat van een simpele race over een rooster een echt tactisch duel maakt, alleen door een paar muren toe te voegen.",
    wallmaze_wall_mode_start: "Muur plaatsen",
    wallmaze_wall_mode_cancel: "✕ Annuleren",
