    wallmaze_wall_confirm: "✓ Plaatsen",
    game_hex: "Hex",
    home_hex_desc: "Verbind je twee zijden van een zeshoekig bord voordat je tegenstander dat doet. Lokaal met z'n tweeën of tegen de ingebouwde engine.",
    hex_legend_r: "Rood: boven onder",
    hex_legend_b: "Blauw: links rechts",
    hex_history_intro: "Een zeldzaam geval waarin hetzelfde eenvoudige, elegante spel twee keer onafhankelijk van elkaar werd uitgevonden, door twee mensen die later om compleet verschillende redenen bekend zouden worden.",
    game_halma: "Halma",
    home_halma_desc: "Race met al je stukken over het bord naar het startkamp van je tegenstander. Lokaal met z'n tweeën of tegen de ingebouwde engine.",
    halma_history_intro: "Een Amerikaanse bewerking van een ouder Duits spel, al ruim een eeuw populair als een eenvoudig te leren race dat toch zorgvuldig plannen beloont.",
    game_sternhalma: "Sterrendam",
    home_sternhalma_desc: "Race met al je tien knikkers over het stervormige bord naar de tegenoverliggende punt. Lokaal met z'n tweeën of tegen de ingebouwde engine.",
    sternhalma_history_intro: "Een afstammeling met stervormig bord van het oudere spel Halma, op de markt gebracht onder een exotische naam die niets te maken heeft met de werkelijke oorsprong.",

    game_dotsandboxes: "Stippen en Vakjes",
    home_dotsandboxes_desc: "Trek lijnen tussen stippen om vakjes te voltooien en te claimen - wie een vakje voltooit, mag meteen nog een keer. Op 4 × 4, 5 × 5, 6 × 6 of 8 × 8 vakjes, lokaal met 2 spelers of tegen de ingebouwde engine.",
    dotsandboxes_new_game: "Nieuw spel",
    dotsandboxes_board_size_label: "Bordgrootte",
    dotsandboxes_board_size_4: "4 × 4 vakjes (korte partij)",
    dotsandboxes_board_size_5: "5 × 5 vakjes",
    dotsandboxes_board_size_6: "6 × 6 vakjes (lange partij)",
    dotsandboxes_board_size_8: "8 × 8 vakjes (zeer lange partij)",
    dotsandboxes_legend_p1: "Speler 1: doorgetrokken lijnen, vakjes met een kruis",
    dotsandboxes_legend_p2: "Speler 2: gestippelde lijnen, vakjes met een cirkel",

    dotsandboxes_history_intro: "Een papier-en-pen-spel van meer dan een eeuw oud, en een serieus onderwerp van wiskundig onderzoek.",
    game_fanorona: "Fanorona",
    home_fanorona_desc: "Het nationale bordspel van Madagaskar: schuif stukken langs de lijnen van een 5x9-raster om te slaan door nadering of terugtrekking. Lokaal met twee spelers of tegen de ingebouwde engine.",
    game_konane: "Konane",
    home_konane_desc: "Hawaiiaans dammen: een volledig bord met afwisselende stenen en orthogonale sprongketens, geopend met een uniek ritueel waarbij twee stenen worden verwijderd. Lokaal met twee spelers of tegen de ingebouwde engine.",

    fanorona_history_intro: "Het nationale bordspel van Madagaskar, en een bron van echte culturele trots en menige legende.",

    fanorona_choose_capture_type: "Er is zowel een slag door nadering als door terugtrekking mogelijk - kies er een:",
    fanorona_capture_approach_btn: "Slaan door nadering",
    fanorona_capture_withdrawal_btn: "Slaan door terugtrekking",
    fanorona_continue_capturing: "Je kunt met dit stuk doorslaan, of hier stoppen.",
    fanorona_done_capturing_btn: "Klaar met slaan",
    game_ludo: "Ludo",
    home_ludo_desc: "Het klassieke kruisvormige racespel, afstammeling van het oude Indiase Pachisi. Speel zelf één kleur tegen maximaal drie computertegenstanders (2 tot 4 spelers in totaal), of speel lokaal om de beurt op hetzelfde apparaat.",
    ludo_mode_hotseat: "Twee spelers, één apparaat",
    ludo_num_players: "Spelers:",
    ludo_roll_die: "Gooien",
    ludo_history_intro: "Een moderne, massaal geproduceerde afstammeling van een van de oudste bordspellen van India.",

    konane_history_intro: "Een traditioneel spel van de oorspronkelijke Hawaiianen, gemaakt van stenen en strategie, rechtstreeks uitgehakt in het land waarop het werd gespeeld.",
    konane_continue_jumping: "Je kunt met deze steen blijven springen, of hier stoppen.",
    konane_done_jumping_btn: "Klaar met springen",
    game_surakarta: "Surakarta",
    home_surakarta_desc: "Het Indonesische vangspel met lusbanen: een gewone stap slaat nooit, alleen een schuif die via een van de 4 hoeklussen van het bord loopt wel. Lokaal met twee spelers of tegen de ingebouwde engine.",
    surakarta_history_intro: "Een traditioneel Indonesisch bordspel, vernoemd naar precies de stad op Java waar het naar men aanneemt is ontstaan.",

    game_marblepush: "Knikkerduw",
    home_marblepush_desc: "Duw 6 knikkers van je tegenstander van het zeshoekige bord om te winnen. Lokaal met twee spelers of tegen de computer, met alle regels voor duwen en voor zijwaartse rijzetten.",
    marblepush_history_intro: "Een duwspel voor twee op een zeshoekig bord, waarin je alleen kunt slaan door de knikkers van de tegenstander over de rand te duwen.",
    marblepush_selection_hint: "Tik op een gemarkeerd veld om deze selectie te verplaatsen, of wis ze hieronder.",
    marblepush_clear_selection_btn: "Selectie wissen",

    game_baghchal: "Bagh-Chal",
    home_baghchal_desc: "Nepals traditionele jachtspel: 4 tijgers tegen 20 geiten op een vierkant 5x5-bord in alquerque-stijl. Lokaal met 2 spelers of tegen de ingebouwde engine, in beide kampen te spelen.",

    baghchal_history_intro: "Nepals meest iconische traditionele bordspel: tijgers die geiten opjagen over een raster van lijnen, met wortels die veel ouder zijn dan enige schriftelijke vastlegging van de regels.",


    game_amazons: "Amazones",
    home_amazons_desc: "Verplaats een amazone die als een dame beweegt, en schiet dan vanaf haar nieuwe veld een blijvende pijl af om het bord stukje bij beetje af te sluiten. Lokaal met 2 spelers of tegen de ingebouwde engine.",
    amazons_history_intro: "Het Spel van de Amazones is een modern abstract strategiespel waarbij je stukje bij beetje gebied verovert door het bord permanent af te sluiten.",

    game_sudoku: "Sudoku",
    home_sudoku_desc: "Vul een 9x9-rooster met cijfers zodat elke rij, kolom en elk 3x3-vak elk cijfer 1-9 precies één keer bevat. Vers gegenereerd met een unieke oplossing, in drie moeilijkheidsgraden.",
    game_peg_solitaire: "Solitaire",
    home_peg_solitaire_desc: "Spring met pinnen over elkaar heen tot er nog maar één over is – op het Engelse kruis of een van meerdere andere borden, van het 6x6-vierkant tot het kruis van Wiegleb met 45 gaten.",
    game_minesweeper: "Minesweeper",
    home_minesweeper_desc: "Ontdek elk veilig vakje met behulp van de cijferaanwijzingen, zonder een verborgen mijn te activeren.",
    game_nonograms: "Nonogrammen",
    home_nonograms_desc: "Gebruik rij- en kolomaanwijzingen om vakje voor vakje een verborgen beeld te onthullen. Een verse, eenduidig oplosbare puzzel in drie formaten.",
    game_2048: "2048",
    home_2048_desc: "Schuif en voeg genummerde tegels samen om 2048 te bereiken voordat het bord vol raakt. Speel daarna door om je beste score nog verder omhoog te drijven.",
    game_mahjong_solitaire: "Mahjong Solitaire",
    home_mahjong_solitaire_desc: "Ruim de gelaagde tegelindeling op door identieke paren te matchen. Elke indeling wordt zo gegenereerd dat er altijd een oplossing is.",
    game_freecell: "FreeCell",
    home_freecell_desc: "Het klassieke kaartsolitaire waarbij bijna elke ronde met de juiste zetten te winnen is. Met volledige supermoves en met één klik verzamelen op de basen.",
    freecell_new_game: "Nieuw spel",
    freecell_collect: "Verzamelen op basen",
    freecell_history_intro: "Een eeuwenoude familie van kaartspellen waarvan de beroemdste variant, ongewoon genoeg, vooral beroemd is dankzij één heel specifiek stuk software uit de jaren 90.",
    game_lightswitch: "Lichtschakelaar",
    home_lightswitch_desc: "Tik op een vakje om het en zijn buren aan en uit te zetten. Zet alle lichtjes uit om te winnen - elke puzzel wordt zo gegenereerd dat er altijd een oplossing is.",
    lightswitch_new_game: "Nieuw spel",
