    lightswitch_level_hard: "Moeilijk (op te lossen in 20 zetten)",
    lightswitch_history_intro: "Een elektronische handheldpuzzel uit de jaren negentig die achter zijn eenvoudige knoppenraster een werkelijk elegant stukje wiskunde bleek te verbergen.",
