    about_devices_link: "Op welke e-readers PaperGames getest is - en hoe je je eigen apparaat controleert",
    devices_intro: "PaperGames draait in de webbrowser van een e-reader. Op welke readers het echt werkt, weet je alleen waar iemand het geprobeerd en teruggemeld heeft. Deze pagina somt die apparaten op en zegt net zo duidelijk wat niet getest is.",
