    devices_step1_text: "Open PaperGames in de eigen browser van je reader. Let erop dat: de pagina laadt, de tekst scherp is en er aan de zijkant niets wordt afgesneden.",
    devices_step2_title: "2. Een spel starten",
    devices_step2_text: "Start een spel, bijvoorbeeld Sudoku of Schaken, en doe een paar zetten. Let erop dat: elke tik op het bedoelde veld terechtkomt en het bord zonder zijwaarts scrollen op het scherm past.",
