    home_bullsandcows_desc: "Kraak een verborgen code van 4 vormen binnen een beperkt aantal pogingen, met behulp van zwarte en witte pinnen als feedback. Herhalingen kunnen toegestaan zijn, afhankelijk van de moeilijkheidsgraad.",

