    home_oldmaid_desc: "Het klassieke kaartspel voor kinderen met dierenplaatjes: paren afleggen, om de beurt een verborgen kaart van je buur trekken – en niet als laatste met de Zwarte Piet blijven zitten. Lezen is niet nodig; tegen 1 tot 3 computers.",
