    game_blockers: "Blokstenen",
    home_blockers_desc: "Een dobbelrace naar het doel boven op het bord voor 2 tot 4 spelers: stenen versperren de paden, en wie op een steen landt, zet hem anderen in de weg. Tegen de computer of met vrienden op één apparaat.",
    bl_level_label: "Niveau",
    bl_board_aria: "Bord Blokstenen",
    bl_history_intro: "Blokstenen is een eigen racespel van PaperGames; het neemt oude elementen van dobbelracespellen over, zoals pionnen naar huis sturen en de weg versperren.",
