    home_blackjack_desc: "Het kaartspel om 21 tegen de bank: kaarten nemen of passen, maar niet boven 21 komen. Twee varianten: 17 en 4 met 32 kaarten en Blackjack met 52. Er wordt gespeeld met fiches, die alleen punten in het spel zijn.",
