    home_canasta_desc: "Het klassieke rummyspel voor twee met 108 kaarten: combinaties van één rang, canasta's van zeven kaarten, jokers en tweeën als wilde kaarten, rode en zwarte drieën. Jij tegen de computer, tot 5000 punten of kort tot 2000.",
