    game_tenpairs: "Tienparen",
    home_tenpairs_desc: "De pen-en-papierpuzzel waarin je cijfers wegstreept: paren die gelijk zijn of samen 10 maken en elkaar zien. Vast? Schrijf de open cijfers opnieuw op. Klassieke start of willekeurig, drie niveaus.",
    tp_history_intro: "Een pen-en-papierpuzzel uit schoolschriften; waar hij vandaan komt, is niet vastgelegd.",
    quickrules_tenpairs_1: "Tik twee cijfers aan die gelijk zijn (3 en 3) of samen 10 maken (3 en 7) om ze weg te strepen.",
    quickrules_tenpairs_2: "Ze moeten elkaar zien: naast elkaar horizontaal, verticaal of diagonaal, of met alleen weggestreepte vakjes ertussen; horizontaal ook over het einde van een rij heen.",
    quickrules_tenpairs_3: "Vast? Tik op Aanvullen: de open cijfers worden aan het eind opnieuw geschreven (hoogstens 5 keer). Streep alle cijfers weg om te winnen.",
