    game_mathcross: "Rekenrooster",
    home_mathcross_desc: "Zet de getallen 1 tot en met 9 elk één keer neer, zodat elke rij en elke kolom klopt - gerekend van links naar rechts. Drie niveaus, altijd precies één oplossing, zonder gokken op te lossen.",
    mc_history_intro: "Een getallenpuzzel met sommen in rijen en kolommen, verwant aan het eeuwenoude magische vierkant van de getallen 1 tot en met 9.",
    quickrules_mathcross_1: "Zet de getallen 1 tot en met 9 in de vakjes, elk precies één keer.",
    quickrules_mathcross_2: "Elke rij en elke kolom moet zijn uitkomst geven. Reken van links naar rechts (van boven naar beneden), zonder dat keer voor plus gaat: 3 + 4 × 2 = 14.",
    quickrules_mathcross_3: "Tik op een vakje en dan op een getal. Een vinkje of kruisje laat zien of een volle rij of kolom klopt.",
    game_cardduel: "Kaartduel",
    home_cardduel_desc: "Een fantasy-kaartspel voor twee magiërs: wezens en spreuken, vier kant-en-klare decks van bos, vuur, water en steen. Tegen de computer in drie niveaus of met z’n tweeën op één apparaat.",
    quickrules_cardduel_1: "Breng de andere magiër van 20 levenspunten naar 0.",
    quickrules_cardduel_2: "Elke beurt heb je 1 kracht meer (tot 10). Tik op een kaart en dan op Spelen: wezens blijven liggen, spreuken werken één keer.",
