    home_villains_desc: "Iedereen speelt een schurk uit de sprookjes van Grimm met een eigen doel – de heks, de wolf, Repelsteeltje en meer – en de anderen zetten helden in de weg. 2 tot 4 spelers, tegen de computer of op één apparaat.",
    quickrules_villains_1: "Bereik als eerste het doel van je schurk – de doelkaart laat zien wat er nog ontbreekt.",
