    ab_item_goldenseed: "Gouden zaadje",
    ab_room_cave_1: "Water druppelt van het plafond in een kleine, heldere poel.",
    ab_room_cave_2: "Blauwe kristallen groeien uit de wanden en gloeien zacht.",
    ab_room_cave_3: "Een smalle gang. Je moet bukken onder een lage rots.",
    ab_room_cave_4: "Oude mijnkarretjes staan op roestige rails. Hier werkte lang geleden iemand.",
    ab_room_cave_5: "De grot komt uit in een hoge hal. Je voetstappen galmen.",
    ab_room_cave_6: "Glinsterend zand bedekt de vloer. Het knerpt onder je laarzen.",
    ab_room_cave_7: "Uit een spleet in de rots waait een koude wind.",
    ab_room_cave_8: "Hier groeien paddenstoelen zo groot als stoelen. Ze ruiken naar aarde.",
    ab_room_cave_9: "Een ondergrondse beek ruist voorbij in een stenen goot.",
    ab_room_cave_10: "Vreemde tekeningen van sterren bedekken een wand.",
    ab_room_cave_11: "Druipstenen hangen als stenen ijspegels van het plafond.",
    ab_room_cave_12: "Een kleine zijgrot. Iemand heeft hier een oude deken laten liggen.",
    ab_room_cave_13: "Het pad klimt over gladde rotsen, glibberig van het mos.",
    ab_room_cave_14: "In een donkere hoek slapen vleermuizen. Je loopt op je tenen.",
    ab_room_cave_15: "Een ronde kamer met een gladde vloer, als gepoetst.",
    ab_room_cave_16: "Groen mos zet de wanden in een bleke gloed.",
    ab_room_cave_17: "Hier ging ooit een touwbrug over. Alleen de palen staan er nog.",
    ab_room_cave_18: "De lucht is hier warm. Ergens diep beneden rommelt iets.",
    ab_room_cave_19: "Overal liggen kristalscherven, alsof er een grote steen is gebarsten.",
    ab_room_cave_20: "Een stil hoekje. Je lamp werpt lange schaduwen.",
    ab_room_tower_1: "Planken vol stoffige boeken reiken tot aan het plafond.",
    ab_room_tower_2: "Een wenteltrap kronkelt omhoog. De treden kraken.",
    ab_room_tower_3: "Raven zitten op een balk en kijken je met glanzende ogen aan.",
    ab_room_tower_4: "Een oude keuken. Boven een koude haard hangt een ketel.",
    ab_room_tower_5: "Door een rond raam zie je diep beneden het bos.",
    ab_room_tower_6: "Een studeerkamer met een enorm bureau. De inkt in de potjes is opgedroogd.",
    ab_room_tower_7: "Achter een glazen wand draaien langzaam tandwielen. Tik, tak.",
    ab_room_tower_8: "Een lange gang met portretten. Hun ogen lijken je te volgen.",
    ab_room_tower_9: "Een kamer vol landkaarten. Een ervan toont een toren zoals deze.",
    ab_room_tower_10: "Op een tafel branden kaarsen, al lijkt er niemand te zijn.",
    ab_room_tower_11: "Een voorraadkamer met potten vol gedroogde kruiden en gekleurde poeders.",
    ab_room_tower_12: "De wind fluit door een kapot luik.",
    ab_room_tower_13: "Een muziekkamer. Een harp speelt helemaal vanzelf een toon.",
    ab_room_tower_14: "Een smalle plankenbrug loopt van de ene muur naar de andere.",
    ab_room_tower_15: "Een slaapkamer met een hemelbed. De gordijnen zitten vol gaten.",
    ab_room_tower_16: "Een werkplaats met een telescoop die naar de hemel wijst.",
    ab_room_tower_17: "Overal op de vloer liggen zwarte veren.",
    ab_room_tower_18: "Aan de muur hangt een spiegel, maar die toont een andere kamer.",
    ab_room_tower_19: "Een klein balkon. Hier boven ruikt de wind naar regen.",
    ab_room_tower_20: "Een koele zaal met een vloer van zwarte en witte tegels.",
    ab_room_forest_1: "Tussen de bomen hangt mist. Je ziet je hand bijna niet.",
    ab_room_forest_2: "Een open plek vol bloemen. Bijen zoemen in de zon.",
    ab_room_forest_3: "Een oud pad, overwoekerd met varens.",
    ab_room_forest_4: "Een holle boom, zo groot dat je erin kunt staan.",
    ab_room_forest_5: "Een kleine vijver. Kikkers springen het water in als je komt.",
    ab_room_forest_6: "Wortels zo dik als armen lopen over het pad.",
    ab_room_forest_7: "Hoog in de boomkruinen zingen vogels.",
    ab_room_forest_8: "Een kring van witte stenen ligt in het gras.",
    ab_room_forest_9: "Braamstruiken groeien langs een stenen muur.",
    ab_room_forest_10: "De grond is zacht en groen van het mos. Het is heel stil.",
    ab_room_forest_11: "Een omgevallen stam ligt als een brug over een greppel.",
    ab_room_forest_12: "Een verlaten hut. De deur hangt open.",
    ab_room_forest_13: "Hoge dennen kraken in de wind.",
    ab_room_forest_14: "Kleine lichtjes dansen boven een moeras.",
    ab_room_forest_15: "Een reusachtige eik met een gezicht in de schors gesneden.",
    ab_room_forest_16: "Paddenstoelen groeien in een volmaakte kring.",
    ab_room_forest_17: "Een beekje kabbelt over gladde kiezels.",
    ab_room_forest_18: "Een donker struikgewas. Takken krassen langs je mouwen.",
    ab_room_forest_19: "Een zonnige heuvel. Van hier zie je de mist beneden als een zee.",
    ab_room_forest_20: "Oude stenen treden lopen tussen twee berken door.",
    home_adventurebook_desc: "Een rollenspel voor één persoon: maak een held, verken kamer voor kamer een grot, een toren of een bos, gooi dobbelstenen voor proeven en gevechten en breng een verloren schat terug. Makkelijk, Gemiddeld of Moeilijk.",
    quickrules_adventurebook_1: "Maak een held, vind dan de schat van de plek en breng hem terug naar de ingang.",
    quickrules_adventurebook_2: "Proeven: twee dobbelstenen plus een waarde moeten het getoonde getal halen. De uitkomst staat er met de som bij.",
    quickrules_adventurebook_3: "Gevechten gaan in rondes: aanvallen, verdedigen, een voorwerp, je klassevaardigheid of vluchten. Het spel slaat na elke stap op.",
