    game_differences: "Zoek de verschillen",
    home_differences_desc: "Twee plaatjes die op 3, 5 of 7 plekken verschillen: iets ontbreekt, heeft een ander patroon, is gespiegeld of verschoven. Tik een verschil aan in een van de twee plaatjes. Zonder tijdsdruk, met een tip als je vastzit. Of een zoekplaat: vind 5 tot 10 dingen op een grote plaat van een kamer - keuken, zolder, tuin en nog negen.",
    df_history_intro: "Een puzzel die bekend is uit kranten, kindertijdschriften en puzzelboekjes; wanneer en waar hij voor het eerst verscheen, is niet betrouwbaar vastgelegd.",
    quickrules_differences_1: "De twee plaatjes verschillen op een paar plekken - 3, 5 of 7, afhankelijk van het niveau.",
    quickrules_differences_2: "Tik een verschil aan in een van de twee plaatjes: het wordt in allebei omcirkeld. Iets kan ontbreken, een ander patroon hebben, gespiegeld of verschoven zijn.",
    quickrules_differences_3: "Er is geen tijdslimiet en geen straf voor verkeerd tikken. Zit je vast? De knop Tip omkadert een gebied met een verschil.",
