    msg_df_search_hint: "Tip: een van de dingen staat op de gemarkeerde plek.",
    game_pentomino: "Pentominopuzzel",
    home_pentomino_desc: "Leg de twaalf stukken van vijf vierkantjes in een rechthoek - draaien en spiegelen met een tik, zonder slepen. Vrij leggen in vier formaten of met gegeven startstukken en precies één oplossing.",
    pt_history_intro: "Twaalf stukken van elk vijf vierkantjes: een puzzel die Henry Dudeney in 1907 publiceerde en die Solomon Golomb in 1953 de naam ‘pentomino's’ gaf.",
    quickrules_pentomino_1: "Vul de rechthoek met de stukken; elk vakje wordt precies één keer bedekt.",
    quickrules_pentomino_2: "Kies een stuk onder het speelveld, draai of spiegel het en tik dan op het vakje waar zijn stip moet komen. Tik op een gelegd stuk om het weer op te pakken.",
    quickrules_pentomino_3: "Bij ‘Startstukken gegeven’ liggen enkele stukken vast en passen de andere op precies één manier.",
    pt_mode_label: "Spelvorm:",
    pt_mode_free: "Vrij leggen",
