    pt_win_title: "Opgelost!",
    msg_pt_choose: "Kies een stuk onder het speelveld.",
    msg_pt_place: "Draai of spiegel het zo nodig en tik dan waar zijn stip moet komen.",
    msg_pt_nofit: "Het stuk past daar niet.",
    msg_pt_fixed: "Dit stuk ligt vast.",
    msg_t_pt_picked: "Stuk {s} opgepakt.",
    msg_pt_won: "De rechthoek is vol - opgelost!",
    msg_t_pt_hint_place: "Tip: stuk {s} hoort op de gemarkeerde plek.",
    msg_t_pt_hint_remove: "Tip: stuk {s} blokkeert de oplossing - haal het weg.",
    msg_pt_hint_none: "Tip: geen weg gevonden - haal een stuk weg.",
    msg_t_pt_info: "Gelegd: {n} van {m} stukken",
    game_arrows: "Pijlen",
    home_arrows_desc: "Tik op een pijl en hij glijdt uit het veld - als er geen andere pijl in de weg staat. Maak het hele veld leeg; elke puzzel is oplosbaar, met ongedaan maken, tips en zonder tijdsdruk. Op Moeilijk en Meester glijden geblokkeerde pijlen door en kunnen ze vast komen te zitten.",
    aw_history_intro: "Stukken die maar één kant op mogen schuiven, zijn familie van de schuifpuzzels die in 1880 een rage werden; de versie met pijlen is een jonge puzzel.",
    quickrules_arrows_1: "Tik op een pijl: hij verlaat het veld in zijn richting als de weg naar de rand vrij is.",
    quickrules_arrows_2: "Staat er een andere pijl in de weg, dan gebeurt er niets - haal die eerst weg. Op Moeilijk en Meester glijdt hij in plaats daarvan door tot die pijl.",
    quickrules_arrows_3: "Maak het hele veld leeg. Elke puzzel is oplosbaar; ‘Tip’ markeert een pijl die eruit kan.",
    aw_win_title: "Veld leeg!",
    aw_aria_cell: "Rij {R}, kolom {C}",
    aw_aria_empty: "leeg",
    aw_aria_arrow: "pijl naar {D}",
    aw_dir_0: "boven",
    aw_dir_1: "rechts",
    aw_dir_2: "beneden",
    aw_dir_3: "links",
    msg_aw_start: "Tik op een pijl om hem uit het veld te sturen.",
    tg_level_outline: "Alleen omtrek",
    game_loosen: "Ringen los",
    home_loosen_desc: "Ringen die in elkaar haken, elk met een opening: draai ze - gehaakte ringen draaien de andere kant op mee - tot ze een voor een loskomen. Drie niveaus, met het minste aantal zetten, ongedaan maken en tips.",
    lr_history_intro: "Ringpuzzels zijn oud - de Chinese ringen werden al rond 1500 beschreven; deze platte vorm met openingen is nieuw.",
    quickrules_loosen_1: "Tik op een ring: hij draait een kwartslag met de klok mee, en de ringen die erin haken draaien de andere kant op.",
    quickrules_loosen_2: "Een ring is los als zijn opening zit waar de gehaakte ring bovenop ligt - tik erop en hij komt eruit.",
    quickrules_loosen_3: "Haal alle ringen eruit; de ringen aan de uiteinden eerst. Tip toont een zet.",
    lr_win_title: "Alles los!",
