    dg_dice_none: "Nog niet gegooid",
    dg_roll: "Gooien",
    game_klappenkasten: "Klappenkasten",
    home_klappenkasten_desc: "Een traditioneel dobbelspel: gooi twee dobbelstenen en klap de genummerde kleppen dicht die samen je worp vormen. Past er niets meer, dan tellen de nog open kleppen tegen je – de minste punten winnen, en alle kleppen dicht wint meteen. Tegen de computer of met maximaal vier spelers op één apparaat.",
    kk_history_intro: "Een traditioneel dobbelspel met een rij genummerde kleppen, gespeeld in kroegen en op schepen – waar en wanneer het precies begon, is niet zeker.",
    quickrules_klappenkasten_1: "Gooi de twee dobbelstenen en klap kleppen dicht die samen de worp vormen – één klep of meer.",
    quickrules_klappenkasten_2: "Blijf gooien en dichtklappen. Past er niets meer, dan zijn de nummers van de open kleppen je punten.",
