    game_steckwuerfeln: "Steckwürfeln",
    home_steckwuerfeln_desc: "Een traditioneel dobbel- en pennenspel met elf gaten genummerd van 2 tot 12: gooi twee dobbelstenen en steek een pen in het gat van de som of in de twee gaten van de afzonderlijke stenen. Blijf gooien zolang er iets past – de vrije gaten tellen tegen je, de minste punten winnen. Varianten: dubbel zes als joker, of één gemeenschappelijk bord waarop afvalt wie niet meer kan steken.",
    sw_history_intro: "Een klein traditioneel dobbelspel op een bord met genummerde gaten en pennen – eenvoudig, oud en nog steeds te koop als houten zakspel.",
    quickrules_steckwuerfeln_1: "Gooi twee dobbelstenen. Steek in het gat van de som of in de twee gaten van de afzonderlijke stenen (2 en 4: gat 6, of gaten 2 en 4).",
    quickrules_steckwuerfeln_2: "Blijf gooien en steken. Past er niets meer, dan zijn de nummers van de vrije gaten je punten.",
    quickrules_steckwuerfeln_3: "De minste punten winnen. Dubbel zes is een joker (opnieuw gooien). ‘Ongedaan maken’ neemt een pen terug.",
