    game_sternjagd: "Sternjagd",
    home_sternjagd_desc: "Een achtervolgingsspel voor twee tot vier spelers met één dobbelsteen: het gegooide getal is precies het aantal stappen langs de pijlen van een stervormig bord. Wie op een tegenstander eindigt, neemt een van zijn drie sterren; eroverheen gaan verandert niets. Wie als laatste nog sterren heeft, wint.",
    sj_history_intro: "Achtervolgingsspelen met een dobbelsteen zijn in veel culturen traditioneel; deze versie heeft een eigen bord met pijlen.",
    quickrules_sternjagd_1: "Gooi de dobbelsteen en zet precies zoveel stappen langs de pijlen. Tik op een van de omcirkelde velden.",
    quickrules_sternjagd_2: "Eindig je zet op een tegenstander om hem te vangen: hij verliest een ster en gaat terug naar een hoek. Eroverheen gaan verandert niets.",
    quickrules_sternjagd_3: "Iedereen heeft drie sterren. Wie als laatste nog sterren heeft, wint. «Ongedaan maken» neemt een zet terug.",
    sj_roll: "Gooi de dobbelsteen",
    sj_roll_hint: "Gooi de dobbelsteen.",
