    game_kleeberg: "Kleeberg",
    home_kleeberg_desc: "Een bouwspel voor twee op een piramide van ronde vakjes: om de beurt zet je harten of klavers op vrije vakjes, maar alleen bovenop twee gevulde vakjes. Drie van je eigen tekens op een rechte lijn winnen.",
    kb_history_intro: "Kleeberg is een nieuw spel met eigen regels; het bouwt voort op het oude idee van drie op een rij.",
    quickrules_kleeberg_1: "Om de beurt: zet een hart of een klaver op een omcirkeld vakje.",
    quickrules_kleeberg_2: "Bouw omhoog: een vakje is pas open als de twee vakjes eronder gevuld zijn.",
    quickrules_kleeberg_3: "Drie van je eigen tekens op een rechte lijn winnen. Is de piramide vol en heeft niemand een lijn, dan is het gelijkspel.",
    kb_move_hint: "Tik op een omcirkeld vakje. Vakjes met een gestippelde rand zijn nog niet open.",
    kb_hearts: "Harten",
    kb_clovers: "Klavers",
    kb_board_aria: "Piramide van vijftien ronde vakjes in vijf rijen",
    kb_goal_aria: "Voorbeeld: drie harten op een rechte lijn",
    kb_goal_text: "Doel: drie van je eigen tekens op een rechte lijn.",
    kb_field_name: "Rij {r}, vakje {c}",
    kb_field_move: "vrij, tik om hier te bouwen",
    kb_field_locked: "nog niet open",
    kb_over_message: "Drie op een rechte lijn winnen. Een volle piramide zonder lijn is gelijkspel.",
    kq_cards_label: "Kaartjes",
    game_oddone: "Welke is anders?",
    home_oddone_desc: "Meerdere kaartjes lijken in één opzicht op elkaar, op één na: tik op het kaartje dat er niet bij hoort. Tekeningen uit dezelfde groep of vormen die in één kenmerk overeenkomen. Zes rondes per spel, drie niveaus, grote knoppen, geen tijdslimiet en een hint als je vastzit.",
    oddone_history_intro: "Het ding vinden dat er niet bij past is een klassieke oefening in schoolboeken en denktests – het traint het ordenen van dingen op hun kenmerken.",
    quickrules_oddone_1: "Meerdere kaartjes lijken in één opzicht op elkaar, op één na.",
    quickrules_oddone_2: "Tik op het kaartje dat er niet bij hoort. Een fout kaartje wordt doorgestreept – probeer een ander.",
    quickrules_oddone_3: "Zes rondes vormen een spel. Er is geen tijdslimiet en de hint markeert het kaartje dat er niet bij hoort.",
    od_win_title: "Alle rondes af!",
    msg_od_start: "Welke hoort er niet bij? Tik erop.",
    msg_od_wrong: "Dit kaartje hoort bij de andere. Probeer een ander.",
    msg_od_hint: "Hint: het gemarkeerde kaartje hoort er niet bij.",
    msg_t_od_won: "Alle rondes af! Fouten: {n}.",
    msg_t_od_won_modal: "Alle rondes af. Fouten: {n}.",
