    kq_shadows_label: "Schaduwen",
    family_picturelogic: "Denkpuzzels met plaatjes",
    game_shadowmatch: "Van wie is de schaduw?",
    home_shadowmatch_desc: "Een plaatje en een paar zwarte schaduwen: welke schaduw hoort erbij? Zes plaatjes per spel, drie niveaus – op moeilijk komt hetzelfde plaatje ook gedraaid of gespiegeld voor. Grote knoppen, geen tijdslimiet en een hint als je vastzit.",
    shadowmatch_history_intro: "Schaduwen worden al eeuwen nagetekend, uitgeknipt en gebruikt om mee te spelen – een schaduw bij zijn voorwerp zoeken is een kleine oefening in goed kijken.",
    quickrules_shadowmatch_1: "Bovenaan staat een plaatje, daaronder staan zwarte schaduwen.",
    quickrules_shadowmatch_2: "Tik op de schaduw die precies de omtrek van het plaatje heeft. Een foute wordt doorgestreept – probeer een andere.",
    quickrules_shadowmatch_3: "Zes plaatjes vormen een spel. Er is geen tijdslimiet en de hint markeert de juiste schaduw.",
    sm_win_title: "Alle plaatjes af!",
