    kq_level_label: "Niveau",
    kq_answers_label: "Antwoorden",
    game_patternrow: "Maak het patroon af",
    home_patternrow_desc: "Een rij symbolen volgt een patroon: welk symbool komt er daarna? Zes rijen per spel, drie niveaus, vormen in zwart-wit, grote antwoordknoppen. Geen tijdslimiet en een hint als je vastzit.",
    patternrow_history_intro: "Rijen met terugkerende tekens zijn zo oud als het pottenbakken en weven – en ze voortzetten is een geliefde opdracht in schoolboeken en tests.",
    quickrules_patternrow_1: "Een rij symbolen herhaalt zich volgens een patroon; de laatste plek is leeg.",
