    msg_aw_glided: "De pijl glijdt door tot de volgende pijl.",
    msg_aw_heart: "Dat kostte een hartje.",
    msg_aw_stuck: "Geen enkele pijl kan nog bewegen - maak een paar zetten ongedaan.",
    msg_aw_lost: "Geen hartjes meer - probeer deze puzzel opnieuw of begin een nieuwe.",
    msg_aw_noway: "Vanaf hier is er geen uitweg - maak een paar zetten ongedaan.",
    msg_aw_hint_glide: "Tip: laat de gemarkeerde pijl doorglijden.",
    msg_t_aw_info_hearts: "Pijlen over: {n} · Zetten: {m} · Hartjes: {k}",
    game_catplaces: "Kattenplekjes",
    home_catplaces_desc: "In elke rij, elke kolom en elke kamer komt precies één kat - en twee katten mogen elkaar niet raken, ook niet met een hoek. Logische puzzels in drie maten, elk met precies één oplossing, op te lossen zonder te gokken.",
    kz_history_intro: "De regels komen van een logische puzzel die in 2003 werd bedacht voor het wereldkampioenschap puzzelen in Nederland; hier nemen slapende katten de plaats van sterren in.",
    quickrules_catplaces_1: "Zet een kat in elke rij, elke kolom en elke kamer (de vlakken binnen de dikke lijnen).",
    quickrules_catplaces_2: "Twee katten raken elkaar nooit - niet naast elkaar en niet met een hoek.",
    quickrules_catplaces_3: "Tik één keer op een vakje voor een kat, nog eens voor een stip (hier geen kat), een derde keer om het leeg te maken. ‘Tip’ wijst een vakje aan.",
