    game_rings: "Ringen draaien",
    home_rings_desc: "Drie tot vijf ringen in elkaar, met vormen erop. Draai de ringen tot elke straal vanuit het midden dezelfde vorm toont - op Moeilijk draait een ring zijn buur mee. Met het minste aantal zetten en een tipknop.",
    rg_history_intro: "Ringen met tekens die tegen elkaar in worden gedraaid, zijn oud: Leon Battista Alberti beschreef in 1467 een codeerschijf van twee draaibare ringen. De puzzel hier is gemaakt voor PaperGames.",
    quickrules_rings_1: "Draai een ring naar links ↺ of naar rechts ↻ met de knoppen onder de afbeelding.",
    quickrules_rings_2: "Doel: elk van de 8 stralen vanuit het midden toont op alle ringen dezelfde vorm.",
    quickrules_rings_3: "Op Moeilijk draait een ring de volgende ring naar buiten mee. ‘Tip’ toont een goede zet; het minste aantal zetten staat erbij.",
