    game_matches: "Lucifersraadsels",
    home_matches_desc: "Leg een of twee lucifers om, zodat een foute som klopt of de figuur het gevraagde aantal vierkanten toont. 90 raadsels in drie niveaus, elk door de computer gecontroleerd; tik op een lucifer en dan op een vrije plek - zonder slepen.",
    mt_history_intro: "Lucifers werden in de 19e eeuw alledaags en al snel ook puzzelmateriaal: het boek Puzzles Old and New (1893) van Professor Hoffmann heeft al een hoofdstuk met lucifersraadsels.",
    quickrules_matches_1: "Tik op een lucifer om hem op te pakken en dan op een vrije plek om hem daar neer te leggen.",
    quickrules_matches_2: "Leg precies zoveel lucifers om als het raadsel zegt: 1 of 2.",
    quickrules_matches_3: "Maak de som goed of maak het gevraagde aantal vierkanten. Ongedaan maken, Opnieuw beginnen en Tip helpen.",
