    msg_t_mt_info: "Verlegd: {n} van {m}",
    game_tangram: "Tangram",
    home_tangram_desc: "Vul een omtrek met de zeven klassieke stukken: driehoeken, een vierkant en een parallellogram. 90 omtrekken in vier niveaus, elk met een door de computer gecontroleerde oplossing. Bij ‘Alleen omtrek’ zie je alleen de buitenlijn en blijft een stuk liggen waar je tikt - je moet proberen. Tik op een stuk, draai het, tik op de plek - niet slepen.",
    tg_history_intro: "Zeven stukken uit één vierkant: de puzzel komt uit China, waar in 1813 het oudste bewaarde boek erover werd gedrukt; vanaf 1817 werd hij een rage in Europa.",
    quickrules_tangram_1: "Kies een stuk onder het silhouet, draai het met ‘Draaien 45°’ of spiegel het, en tik dan waar het moet komen.",
    quickrules_tangram_2: "Vul het hele silhouet met alle zeven stukken; ze mogen niet overlappen.",
